CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS hotel_guests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),guest_no text NOT NULL,first_name text NOT NULL,last_name text NOT NULL,phone text,email text,status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,guest_no));
CREATE TABLE IF NOT EXISTS hotel_room_types(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),name text NOT NULL,capacity int NOT NULL DEFAULT 1,base_rate numeric(12,2) NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'active',UNIQUE(tenant_id,name));
CREATE TABLE IF NOT EXISTS hotel_rooms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),room_no text NOT NULL,room_type_id uuid NOT NULL REFERENCES hotel_room_types(id),floor text,status text NOT NULL DEFAULT 'available',UNIQUE(tenant_id,room_no));
CREATE TABLE IF NOT EXISTS hotel_bookings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),booking_no text NOT NULL,guest_id uuid NOT NULL REFERENCES hotel_guests(id),room_id uuid REFERENCES hotel_rooms(id),check_in_date date NOT NULL,check_out_date date NOT NULL,adults int NOT NULL DEFAULT 1,children int NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'booked',total_amount numeric(14,2) NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,booking_no));
CREATE TABLE IF NOT EXISTS hotel_payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),booking_id uuid NOT NULL REFERENCES hotel_bookings(id),amount numeric(14,2) NOT NULL CHECK(amount>0),method text NOT NULL,reference text,paid_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS hotel_housekeeping(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),room_id uuid NOT NULL REFERENCES hotel_rooms(id),status text NOT NULL DEFAULT 'pending',assigned_to uuid REFERENCES users(id),notes text,updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_hotel_guests_tenant ON hotel_guests(tenant_id); CREATE INDEX IF NOT EXISTS idx_hotel_rooms_tenant ON hotel_rooms(tenant_id,status); CREATE INDEX IF NOT EXISTS idx_hotel_bookings_tenant_dates ON hotel_bookings(tenant_id,check_in_date,check_out_date);